    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        int total = scan.nextInt();
        if (total <= 11) {
            long[][] pointsData = new long[total][5];

            for (int i = 0; i < total; i++) {
                for (int j = 0; j < 5; j++) {
                    pointsData[i][j] = scan.nextLong();
                }
            }

            long[][][] vectorsArray = new long[total][total][5];
            for (int i = 0; i < total; i++) {
                for (int j = 0; j < total; j++) {
                    for (int k = 0; k < 5; k++) {
                        vectorsArray[i][j][k] = pointsData[j][k] - pointsData[i][k];
                    }
                }
            }

            HashSet<Integer> excludedIndices = new HashSet<>();

            for (int i = 0; i < total; i++) {
                boolean breakFlag = false;
                for (int j = 0; j < total; j++) {
                    for (int k = 0; k < total; k++) {
                        if (!areVectorsEqual(vectorsArray[i][j], vectorsArray[i][k]) && isDotPositive(vectorsArray[i][j], vectorsArray[i][k])) {
                            excludedIndices.add(i + 1);
                            breakFlag = true;
                            break;
                        }
                    }
                    if (breakFlag) break;
                }
            }

            System.out.println(total - excludedIndices.size());
            for (int i = 0; i < total; i++) {
                if (!excludedIndices.contains(i + 1))
                    System.out.println(i + 1);
            }
        } else {
            System.out.println(0);
        }
    }

    private static boolean areVectorsEqual(long[] a, long[] b) {
        for (int i = 0; i < 5; i++) {
            if (a[i] != b[i]) return false;
        }
        return true;
    }

    private static boolean isDotPositive(long[] a, long[] b) {
        long sum = 0;
        for (int i = 0; i < 5; i++) {
            sum += a[i] * b[i];
        }
        return sum > 0;
    }
}
