import sys

def are_vectors_equal(a, b):
    for i in range(5):
        if a[i] != b[i]:
            return False
    return True

def is_dot_positive(a, b):
    total = 0
    for i in range(5):
        total += a[i] * b[i]
    return total > 0

def main():
    input_data = sys.stdin.read().strip().split()
    total = int(input_data[0])
    if total <= 11:
        pointsData = []
        index = 1
        for _ in range(total):
            point = list(map(int, input_data[index:index+5]))
            index += 5
            pointsData.append(point)

        vectorsArray = [[[0]*5 for _ in range(total)] for _ in range(total)]
        for i in range(total):
            for j in range(total):
                for k in range(5):
                    vectorsArray[i][j][k] = pointsData[j][k] - pointsData[i][k]

        excludedIndices = set()

        for i in range(total):
            breakFlag = False
            for j in range(total):
                for k in range(total):
                    if not are_vectors_equal(vectorsArray[i][j], vectorsArray[i][k]) and is_dot_positive(vectorsArray[i][j], vectorsArray[i][k]):
                        excludedIndices.add(i + 1)
                        breakFlag = True
                        break
                if breakFlag:
                    break

        print(total - len(excludedIndices))
        for i in range(1, total + 1):
            if i not in excludedIndices:
                print(i)
    else:
        print(0)

if __name__ == "__main__":
    main()

